};

enum class CostAggMode : int {
    SUM = 0, // 多组 cost 求和
    MAX = 1, // 多组 cost 取最大值
};

// CalcCostCoeff 的参数结构体，新增参数只需在此结构体加成员，无需改动所有调用点签名
struct CalcCostCoeffParam {
    u32 rankSize = 0;
    float n = 0.0f;
    AlgNetType netType = AlgNetType::MESH;
    bool needLocalCopy = true;
    const char* algName = nullptr;
