#include <memory>
#include <mutex>
#include <string>
#include "alg_v2_template_base.h"

namespace ops_hccl {

using InsAlgTemplateCreator = std::function<InsAlgTemplateBase*()>;

template <typename P>
static InsAlgTemplateBase* DefaultTemplateCreatorV2()
{
    static_assert(
        std::is_base_of<InsAlgTemplateBase, P>::value, "Template type must derived from Hccl::InsAlgTemplateBase");
    return new (std::nothrow) P();
}

class InsAlgTemplateRegistry {
public:
    static InsAlgTemplateRegistry& Instance();
    InsAlgTemplateRegistry() {};
    HcclResult Register(const std::string& name, const InsAlgTemplateCreator& algTemplateCreator);
    std::unique_ptr<InsAlgTemplateBase> GetAlgTemplate(const std::string& name);

private:
    std::map<std::string, InsAlgTemplateCreator> tempCreators_;
    mutable std::mutex mu_;
};

#define REGISTER_TEMPLATE_V2_HELPER(ctr, name, insAlgTempBase) \
    static HcclResult g_func_##insAlgTempBase##_##ctr          \
        = InsAlgTemplateRegistry::Instance().Register(name, DefaultTemplateCreatorV2<insAlgTempBase>)

#define REGISTER_TEMPLATE_V2(name, insAlgTempBase) REGISTER_TEMPLATE_V2_HELPER(__COUNTER__, name, insAlgTempBase)

} // namespace ops_hccl
===
InsAlgTemplateRegistry& InsAlgTemplateRegistry::Instance()
{
    static InsAlgTemplateRegistry globalTempRegistry;
    return globalTempRegistry;
}

HcclResult InsAlgTemplateRegistry::Register(const std::string& name, const InsAlgTemplateCreator& algTemplateCreator)
{
    const std::lock_guard<std::mutex> lock(mu_);
    if ((tempCreators_.find(name) != tempCreators_.end()) && (tempCreators_[name] != nullptr)) {
        HCCL_ERROR("[InsAlgTemplateRegistry]template name[%s] already registered.", name.c_str());
        return HcclResult::HCCL_E_INTERNAL;
    }
    tempCreators_[name] = algTemplateCreator;
    return HcclResult::HCCL_SUCCESS;
}

std::unique_ptr<InsAlgTemplateBase> InsAlgTemplateRegistry::GetAlgTemplate(const std::string& name)
{
    if (tempCreators_.find(name) == tempCreators_.end()) {
        HCCL_ERROR("[InsAlgTemplateRegistry]template name[%s] not found.", name.c_str());
        return nullptr;
    }

    if (tempCreators_[name] == nullptr) {
        HCCL_DEBUG("[InsAlgTemplateRegistry]Creator for template name[%s] has not registered.", name.c_str());
        return nullptr;
    }
    HCCL_DEBUG("[InsAlgTemplateRegistry][GetAlgTemplate]get template by name[%s]", name.c_str());
    return std::unique_ptr<InsAlgTemplateBase>(tempCreators_[name]());
}

} // namespace ops_hccl
